... By handing the language model the complete problem text we give it the necessary information to write a correct solution, while everything else in the pipeline can stay unchanged.  The modification is therefore to build the chat prompt from `problem["prompt"]` (falling back to `description` for safety).  No other parameters are touched, so this is an atomic, easily measurable improvement.

```python
# file: solution/solve_code_contests_rust.py
from __future__ import annotations
import asyncio, logging, json, pathlib, random, argparse, os, sys
from typing import Any

import openai, backoff

# -----------------------------------------------------------------------------
# 1. PROMPT ENGINEERING
# -----------------------------------------------------------------------------
FEW_SHOT_EXAMPLES = [
    (
        "Read two integers and output their sum.",
        """use std::io::{self, Read};
fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace().map(|x| x.parse::<i64>().unwrap());
    let a = it.next().unwrap();
    let b = it.next().unwrap();
    println!("{}", a + b);
}""",
    ),
    (
        "Given n (n<=100) followed by n integers, print the maximum.",
        """use std::io::{self, Read};
fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.split_whitespace().map(|x| x.parse::<i64>().unwrap());
    let n = it.next().unwrap() as usize;
    let mut max_val = std::i64::MIN;
    for _ in 0..n { max_val = max_val.max(it.next().unwrap()); }
    println!("{}", max_val);
}""",
    ),
]

SYSTEM_PROMPT = """You are an expert competitive-programming assistant.
You must output ONLY compilable Rust 1.70-compatible source code in a single file.
Do NOT import external crates; rely solely on the standard library.
Use fast I/O (read_to_string + split_whitespace).
Print nothing except the required answers.
"""


def _get_statement(problem: dict[str, Any]) -> str:
    """
    CodeContests stores the full problem text in the ``prompt`` field.
    Fall back to ``description`` or a JSON dump if necessary.
    """
    return (
        problem.get("prompt")
        or problem.get("description")
        or json.dumps(problem, ensure_ascii=False)
    )


def build_prompt(problem: dict[str, Any]) -> list[dict[str, str]]:
    msgs: list[dict[str, str]] = [{"role": "system", "content": SYSTEM_PROMPT}]
    # few-shot
    for desc, code in FEW_SHOT_EXAMPLES:
        msgs.append({"role": "user", "content": desc})
        msgs.append({"role": "assistant", "content": code})
    # actual problem
    msgs.append({"role": "user", "content": _get_statement(problem)})
    return msgs


# -----------------------------------------------------------------------------
# 2. SOLUTION GENERATION
# -----------------------------------------------------------------------------
@backoff.on_exception(backoff.expo, Exception, max_time=300)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    async with semaphore:  # one request at a time per semaphore slot
        completion = (
            (
                await client.chat.completions.create(
                    model="gpt-3.5-turbo-0125",
                    temperature=0.2,
                    max_tokens=1700,
                    messages=build_prompt(problem),
                )
            )
            .choices[0]
            .message.content
        )
    return completion.strip()


# -----------------------------------------------------------------------------
# 3. OPTIONAL LOCAL VALIDATION (on ./data/valid.jsonl)
# -----------------------------------------------------------------------------
async def _run_validation():
    """
    Runs the official evaluation on a small subset of the public validation set
    so we can quickly see that the new prompt logic works end-to-end.
    """
    import score as score_mod  # provided by the competition environment

    valid_path = pathlib.Path("data/valid.jsonl")
    if not valid_path.exists():
        print("Validation set not found – skipping metric computation.")
        return

    args = score_mod.parse_args(
        f"--problems_file={valid_path}",
        f"--module_path={pathlib.Path(__file__).resolve()}",
        "--max_problems=20",  # small sample for speed
        "--strip_score_information",
    )
    result = await score_mod.evaluate_dataset(**args)
    print(
        f"Validation success ratio on {result['message']['n_problems']} problems: {result['score']:.4f}"
    )


# -----------------------------------------------------------------------------
# 4. CLI ENTRY-POINT
# -----------------------------------------------------------------------------
if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--eval", action="store_true", help="run quick validation")
    opts = parser.parse_args()
    if opts.eval:
        asyncio.run(_run_validation())
    else:
        print("Module imported – ready for scoring.")
