        .map(|s| s.parse::<i64>().unwrap())
        .max()
        .unwrap();
    println!("{}", max);
}""",
    },
]


def get_prompt(problem):
    prompt = ""
    for example in EXAMPLE_PROBLEMS:
        prompt += f"""Problem Description:
{example['description']}

Rust Solution:
{example['solution']}

"""
    prompt += f"""Now, solve the following problem:

Problem Description:
{problem['description']}

Provide a Rust program that reads from standard input and writes to standard output.

Here are some example input/output pairs:
"""
    public_tests = problem.get("public_tests", {})
    inputs = public_tests.get("input", [])
    outputs = public_tests.get("output", [])

    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        prompt += f"Input {i+1}:\n{inp}\nOutput {i+1}:\n{outp}\n\n"

    prompt += """Ensure your program passes these tests and adheres to the input/output format.

Provide only the Rust code without any explanations or comments."""
    return prompt


@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: Dict[str, Any],
) -> str:
    prompt = get_prompt(problem)
    async with semaphore:
        response = await client.chat_completions.create(
            model="gpt-3.5-turbo",
            messages=[
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": prompt},
            ],
            max_tokens=MAX_TOKENS,
            temperature=TEMPERATURE,
            n=1,
        )
        completion = response.choices[0].message.content
    return completion


async def evaluate_solutions(
    semaphore: asyncio.Semaphore,
    problem: Dict[str, Any],
    codes: List[str],
) -> Tuple[Dict[str, Any], str]:
    async def evaluate_code(code):
        scratch_dir = tempfile.mkdtemp()
        try:
            result = await evaluate_rust_code(semaphore, problem, code, scratch_dir)
        finally:
            shutil.rmtree(scratch_dir)
        return result, code

    tasks = [evaluate_code(code) for code in codes]
    results_with_codes = await asyncio.gather(*tasks)

    # Select the solution that passed public tests, or with most passed tests
    results_with_codes.sort(
        key=lambda x: (
            x[0].get("succeeded", False),
            x[0].get("frac_public_tests_passed", 0),
        ),
        reverse=True,
    )
    best_result, best_code = results_with_codes[0]
    return best_result, best_code


async def main():
    # Load the validation dataset
    with open("data/valid.jsonl", "r") as f:
        problems = [json.loads(line) for line in f]

    # Semaphores to limit concurrency
    api_semaphore = asyncio.Semaphore(5)  # Limit OpenAI API calls
    eval_semaphore = asyncio.Semaphore(5)  # Limit code evaluations

    # Set OpenAI API key
    api_key = open("api_key.txt").read().strip()
    openai.api_key = api_key

    successes = []

    async with openai.AsyncOpenAI(api_key=api_key) as client:
        async def process_problem(problem):
            codes = []
            for _ in range(N_SAMPLES):
                code = await generate_solution(client, api_semaphore, problem)
                codes.append(code)
            best_result, best_code = await evaluate_solutions(
                eval_semaphore, problem, codes
            )
            if best_result.get("succeeded"):
                successes.append(1)
            else:
                successes.append(0)

        tasks = [process_problem(problem) for problem in problems]
        await tqdm.gather(*tasks, desc="Processing problems")

    score = sum(successes) / len(successes)
    print(f"Validation Metric: {score:.6f}")


if __name__ == "__main__":
    asyncio.run(main())
