from collections import Counter

def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def find_key_length(ciphertext, max_length=20):
    scores = []
    for length in range(1, max_length + 1):
        chunks = [ciphertext[i:i+length] for i in range(0, len(ciphertext), length)]
        score = sum(chunk.count(chunks[0][0]) for chunk in chunks) / len(chunks)
        scores.append((length, score))
    return max(scores, key=lambda x: x[1])[0]

def decrypt_with_key_length(ciphertext, key_length):
    key = b''
    for i in range(key_length):
        column = ciphertext[i::key_length]
        key += bytes([Counter(column).most_common(1)[0][0] ^ ord('e')])  # Assume 'e' is the most common character
    return xor_bytes(ciphertext, key * (len(ciphertext) // len(key) + 1))

