def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def is_printable(byte):
    return 32 <= byte <= 126

def decrypt_and_extend_key(ciphertext, partial_key):
    key = bytearray(partial_key)
    decrypted = bytearray()

    for i in range(len(ciphertext)):
        if i < len(key):
            decrypted.append(ciphertext[i] ^ key[i])
        else:
            for byte in range(256):
                if is_printable(ciphertext[i] ^ byte):
                    key.append(byte)
                    decrypted.append(ciphertext[i] ^ byte)
                    break
            else:
                return None, None

    return bytes(decrypted), bytes(key)

encrypted_hex = "57657535570c1e1c612b3468106a18492140662d2f5967442a2960684d28017931617b1f3637"
ciphertext = bytes.fromhex(encrypted_hex)

known_start = b"picoCTF{"
initial_key = xor_bytes(ciphertext[:len(known_start)], known_start)

decrypted, key = decrypt_and_extend_key(ciphertext, initial_key)

if decrypted:
    print("Decrypted message:", decrypted)
    print("Decoded message:", decrypted.decode('ascii', errors='ignore'))
    print("Key:", key)
else:
    print("Failed to decrypt the message")

