import gmpy2
import random

def long_to_bytes(n):
    return n.to_bytes((n.bit_length() + 7) // 8, byteorder='big')

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def optimized_p_minus_1(n, B1, B2, max_attempts=10):
    primes = [2]
    for i in range(3, B2, 2):
        if all(i % p != 0 for p in primes):
            primes.append(i)

    for _ in range(max_attempts):
        a = random.randint(2, n-1)
        d = gcd(a, n)
        if d > 1:
            return d

        # First stage: small primes
        for p in primes:
            if p > B1:
                break
            a = pow(a, p, n)

        g = gcd(a-1, n)
        if 1 < g < n:
            return g

        # Second stage: larger primes
        for p in primes:
            if p > B2:
                break
            if p <= B1:
                continue
            a = pow(a, p, n)
            g = gcd(a-1, n)
            if 1 < g < n:
                return g

    return None

