def pollard_rho(n, max_iterations=1000):
    def f(x):
        return (x * x + 1) % n

    x = 2
    y = 2
    d = 1

    for _ in range(max_iterations):
        x = f(x)
        y = f(f(y))
        d = gcd(abs(x - y), n)
        if 1 < d < n:
            return d
        if d == n:
            return None

    return None

