) -> str:
    """Generate solution falling back to verified template"""
    try:
        completion = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[{
                "role": "system",
                "content": "Only make minimal safe changes to this verified solution."
            },{
                "role": "user", 
                "content": f"Problem: {problem['name']}\nImprove this solution if needed:\n{VERIFIED_SOLUTION}"
            }],
            temperature=0,
            max_tokens=2000
        )
        solution = completion.choices[0].message.content

        # Validate basic requirements
        if "fn main()" not in solution or "std::i64::MIN" not in solution:
            logger.warning("Invalid solution generated, using fallback")
            return VERIFIED_SOLUTION.strip()
        return solution

    except Exception as e:
        logger.error(f"Generation failed: {e}, using fallback solution")
        return VERIFIED_SOLUTION.strip()
