def get_prompt(problem):
    # Create a prompt including multiple sample problems and their solutions
    prompt = "You are an experienced competitive programmer. Please write Rust code to solve programming problems as shown in the examples below.\n\n"
    for example in FEW_SHOT_EXAMPLES:
        prompt += f"Example Problem:\n{example['description']}\n\nExample Solution:\n// Rust code\n{example['solution']}\n\n"

    prompt += f"Now, solve the following problem.\n\n"
    prompt += f"Problem Description:\n{problem['description']}\n\n"

    if problem.get("constraints"):
        prompt += f"Constraints:\n{problem['constraints']}\n\n"

    if problem.get("input_format"):
        prompt += f"Input Format:\n{problem['input_format']}\n\n"

    if problem.get("output_format"):
        prompt += f"Output Format:\n{problem['output_format']}\n\n"

    # Include public test cases as examples
    public_tests = problem.get("public_tests", {})
    if public_tests.get("input") and public_tests.get("output"):
        prompt += f"Examples:\n"
        for i, (test_input, test_output) in enumerate(
            zip(public_tests.get("input", []), public_tests.get("output", []))
        ):
            prompt += f"Input {i+1}:\n{test_input.strip()}\nOutput {i+1}:\n{test_output.strip()}\n"

    prompt += """
Please write a complete Rust program that reads input from stdin and writes output to stdout, without any additional text or explanations."""
    return prompt


@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    prompt = get_prompt(problem)
    async with semaphore:
        completion = (
            (
                await openai.ChatCompletion.acreate(
                    model="gpt-3.5-turbo-0125",
                    max_tokens=1600,
                    temperature=0,
                    messages=[
                        {
                            "role": "system",
                            "content": "You are an expert competitive programmer specializing in Rust programming. You write clear and correct code that passes all test cases.",
                        },
                        {"role": "user", "content": prompt},
                    ],
                )
            )
            .choices[0]
            .message.content
        )
    return completion


async def main():
    api_key = open("api_key.txt").read().strip()
    openai.api_key = api_key

    # Load validation problems
    with open("data/valid.jsonl", "r") as f:
        problems = [json.loads(line) for line in f]

    semaphore = asyncio.Semaphore(5)

    success_count = 0
    total_count = len(problems)

    results = []
    for problem in tqdm(problems):
        rust_code = await generate_solution(semaphore, problem)
        scratch_dir = "./working"
        pathlib.Path(scratch_dir).mkdir(exist_ok=True)
        evaluation = await evaluate_rust_code(
            semaphore, problem, rust_code, scratch_dir
        )
        if evaluation["succeeded"]:
            success_count += 1
        results.append(evaluation)

    # Compute evaluation metric
    score = success_count / total_count
    print(f"{score}")


if __name__ == "__main__":
    asyncio.run(main())
