The main issues in the previous implementation need to be fixed by: 1) Removing the natural language text at the beginning and ensuring proper code formatting. 2) Adding better error handling and retries for the OpenAI API calls, including proper timeout management. 3) Implementing robust code extraction from the API response with proper Rust boilerplate generation.

```python
from __future__ import annotations
import asyncio
import logging
import re
from typing import Any
import backoff
import openai

logging.getLogger("backoff").addHandler(logging.StreamHandler())

def extract_rust_code(completion: str) -> str:
    code_block = re.search(r"```(?:rust)?\n(.*?)\n```", completion, re.DOTALL)
    if code_block:
        code = code_block.group(1).strip()
    else:
        code_match = re.search(r"(?:^|\n)(?:pub\s+)?fn\s+main.*?}[\s]*$", completion, re.DOTALL)
        if code_match:
            code = code_match.group(0).strip()
        else:
            code = completion.strip()

    boilerplate = []
    if "use std::io" not in code:
        boilerplate.append("use std::io;")
    if "fn main()" not in code:
        code = f"fn main() {{\n    {code}\n}}"

    return "\n".join(boilerplate + [code])

def get_prompt(problem: dict[str, Any]) -> str:
    test_examples = ""
    if problem.get("public_tests"):
        inputs = problem["public_tests"].get("input", [])
        outputs = problem["public_tests"].get("output", [])
        if inputs and outputs:
            test_examples = "\nTest Cases:\n"
            for i, (inp, out) in enumerate(zip(inputs, outputs), 1):
                test_examples += f"Input {i}:\n{inp.strip()}\nExpected Output {i}:\n{out.strip()}\n"

    return f"""Write a Rust solution for this competitive programming problem.

Problem: {problem['name']}

Description:
{problem['description']}

Input Format:
{problem.get('input_format', 'Not specified')}

Output Format:
{problem.get('output_format', 'Not specified')}

Constraints:
{problem.get('constraints', 'Not specified')}
{test_examples}

Requirements:
1. Use standard input/output (stdin/stdout)
2. Handle all edge cases within constraints
3. Follow exact output format
4. Include proper error handling
5. Return only compilable Rust code

Return complete code in markdown format."""

@backoff.on_exception(
    backoff.expo,
    (openai.RateLimitError, openai.APIError, asyncio.TimeoutError),
    max_tries=3,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI, 
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any]
) -> str:
    async with semaphore:
        try:
            completion = await asyncio.wait_for(
                client.chat.completions.create(
                    model="gpt-3.5-turbo-0125",
                    messages=[
                        {"role": "system", "content": "You are an expert Rust programmer specializing in competitive programming solutions."},
                        {"role": "user", "content": get_prompt(problem)}
                    ],
                    max_tokens=1600,
                    temperature=0.2,
                    presence_penalty=0.1,
                    frequency_penalty=0.1,
                ),
                timeout=30
            )
            return extract_rust_code(completion.choices[0].message.content)
        except Exception as e:
            logging.error(f"Error generating solution for {problem['name']}: {str(e)}")
            raise

async def evaluate_solutions():
    with open("api_key.txt") as f:
        api_key = f.read().strip()

    client = openai.AsyncOpenAI(api_key=api_key)
    semaphore = asyncio.Semaphore(1)

    test_problem = {
        "name": "Sum Two Numbers",
        "description": "Given two integers, output their sum.",
        "input_format": "Two space-separated integers a and b",
        "output_format": "Single integer - sum of a and b",
        "constraints": "1 ≤ a,b ≤ 1000",
        "public_tests": {
            "input": ["2 3\n"],
            "output": ["5\n"]
        }
    }

    solution = await generate_solution(client, semaphore, test_problem)
    print(solution)

if __name__ == "__main__":
    asyncio.run(evaluate_solutions())
```

