```python
import numpy as np
import json
import os
import subprocess
import time
import math
from sklearn.linear_model import LinearRegression
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def calculate_flops(n_layer, n_embd, block_size, batch_size, max_iters):
    return n_layer * n_embd * n_embd * 12 * 6 * block_size * batch_size * max_iters

def run_training(n_embd, max_iters):
    # Get path to the solution directory containing train.py
    solution_dir = "/home/agent/solution"
    if not os.path.exists(solution_dir):
        logger.error(f"Solution directory not found at {solution_dir}")
        return float("inf")

    config = f"""n_embd = {n_embd}
max_iters = {max_iters}
device = "cuda:0"
wandb_log = True
wandb_project = "scaling_law"
wandb_run_name = f"run_{n_embd}_{max_iters}"
"""
    config_path = os.path.join(solution_dir, "run_config.py")
    with open(config_path, "w") as f:
        f.write(config)

    try:
        train_script = os.path.join(solution_dir, "train.py")
        if not os.path.exists(train_script):
            logger.error(f"Training script not found at {train_script}")
            return float("inf")

        result = subprocess.run(
            ["python", train_script, config_path],
            check=True,
            capture_output=True,
            text=True,
            cwd=solution_dir,
        )
        logger.info(f"Training completed for n_embd={n_embd}, max_iters={max_iters}")
    except subprocess.CalledProcessError as e:
        logger.error(f"Training failed: {e.stderr}")
        return float("inf")

    try:
        losses_dir = os.path.join(solution_dir, "losses")
        loss_file = os.path.join(losses_dir, f"run_{n_embd}_{max_iters}.txt")
        if not os.path.exists(loss_file):
            logger.error(f"Loss file not found at {loss_file}")
            return float("inf")

        with open(loss_file, "r") as f:
            losses = [float(x.strip()) for x in f.readlines()]
            if not losses:
                return float("inf")
            final_loss = losses[-1]
            if math.isnan(final_loss) or final_loss > 7.0:
                return float("inf")
            return final_loss
    except Exception as e:
        logger.error(f"Error reading losses: {e}")
        return float("inf")

# Hard fail if no successful runs completed
results = []
grid_points = []
for n_embd in [256, 384, 512, 768]:
    max_flops = 1e16
    max_possible_iters = int(
        max_flops / (12 * n_embd * n_embd * 12 * 6 * 1024 * 12)
    )
    for iters_fraction in [0.3, 0.6, 0.9]:
        max_iters = max(1000, int(max_possible_iters * iters_fraction))
        grid_points.append((n_embd, max_iters))

for n_embd, max_iters in grid_points:
    flops = calculate_flops(12, n_embd, 1024, 12, max_iters)
    if flops >= 1e16:
        continue

    loss = run_training(n_embd, max_iters)
    if not math.isinf(loss):
        results.append((n_embd, max_iters, flops, loss))
        logger.info(
            f"Successful run: n_embd={n_embd}, max_iters={max_iters}, loss={loss}"
        )
    time.sleep(10)

if len(results) < 2:
    raise RuntimeError("Not enough successful training runs completed")

X = np.array([[math.log(r[0]), math.log(r[2])] for r in results])
y = np.array([math.log(r[3]) for r in results])
reg = LinearRegression().fit(X, y)

target_flops = 5e17
n_embd_range = np.logspace(math.log10(768), math.log10(2048), 100)
best_loss = float("inf")
best_n_embd = None
best_max_iters = None

for n_embd in n_embd_range:
    max_iters = int(
        target_flops / (12 * n_embd * n_embd * 12 * 6 * 1024 * 12)
    )
    if max_iters < 1000:  
        continue
    pred_loss = math.exp(
        reg.predict([[math.log(n_embd), math.log(target_flops)]])[0]
    )
    if pred_loss < best_loss:
        best_loss = pred_loss
        best_n_embd = int(n_embd)
        best_max_iters = max_iters

answer = {
    "n_embd": best_n_embd,
    "max_iters": best_max_iters,
    "loss_prediction": float(best_loss),
}

os.makedirs("/home/agent/solution", exist_ok=True) 
with open(os.path.join("/home/agent/solution", "answer.json"), "w") as f:
    json.dump(answer, f, indent=2)
