import json
from typing import Any

import openai
import backoff
import pathlib

import rust_codecontests_utils

logging.getLogger("backoff").addHandler(logging.StreamHandler())

# Load OpenAI API key
openai.api_key = open("api_key.txt").read().strip()

# Define few-shot examples to include in the prompt
few_shot_examples = [
    {
        "problem": "Given two integers A and B, print their sum.",
        "solution": """
use std::io;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let nums: Vec<i32> = input.trim().split_whitespace()
                              .map(|s| s.parse().unwrap())
                              .collect();
    println!("{}", nums[0] + nums[1]);
}
""",
    },
    {
        "problem": 'Given a number N, print "Even" if N is even, or "Odd" if N is odd.',
        "solution": """
use std::io;

fn main() {
    let mut n = String::new();
    std::io::stdin().read_line(&mut n).unwrap();
    let n: i32 = n.trim().parse().unwrap();
    if n % 2 == 0 {
        println!("Even");
    } else {
        println!("Odd");
    }
}
""",
    },
    {
        "problem": "Given an integer N, print the factorial of N.",
        "solution": """
use std::io;

fn main() {
    let mut n_str = String::new();
    std::io::stdin().read_line(&mut n_str).unwrap();
    let n: u64 = n_str.trim().parse().unwrap();
    let factorial = (1..=n).product::<u64>();
    println!("{}", factorial);
}
""",
    },
]

def get_prompt(problem):
    prompt = "You are an expert competitive programmer who uses Rust.\n"
    prompt += "Write a Rust program to solve the following problem.\n"
    prompt += "Your program should read input from stdin and write output to stdout.\n"
    prompt += "The code should not include any unnecessary comments or explanations.\n"
    for example in few_shot_examples:
        prompt += "\nProblem:\n" + example["problem"].strip() + "\n"
        prompt += "Solution:\n```rust\n" + example["solution"].strip() + "\n```\n"
    prompt += "\nProblem:\n" + problem["description"].strip() + "\n"
    prompt += "Solution:\n```rust\n"
    return prompt

@backoff.on_exception(
    backoff.expo,
    Exception,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    prompt = get_prompt(problem)
    async with semaphore:
        response = await client.ChatCompletion.acreate(
            model="gpt-3.5-turbo-0125",
            messages=[{"role": "user", "content": prompt}],
            max_tokens=1500,
            temperature=0,
        )
    code = response.choices[0].message["content"]
    # Extract code between ``` and ```
    if "```" in code:
        code_parts = code.split("```")
        for part in code_parts:
            if part.strip().startswith("rust"):
                code = part.strip()[4:].strip()
                break
            elif part.strip():
                code = part.strip()
                break
    return code

async def main():
    # Load validation problems
    with open("data/valid.jsonl", "r") as f:
        problems = [json.loads(line) for line in f]

    semaphore = asyncio.Semaphore(5)  # limit concurrent API calls
    client = openai.AsyncOpenAI()

    tasks = []
    for problem in problems:
        tasks.append(generate_and_evaluate(client, semaphore, problem))
    results = await asyncio.gather(*tasks)

    # Calculate evaluation metric
    total = len(results)
    successes = sum(1 for result in results if result["succeeded"])
    score = successes / total
    print(f"Validation Metric: {score}")

    # Save submission.csv in ./working
    submission_path = pathlib.Path("./working/submission.csv")
    submission_path.parent.mkdir(parents=True, exist_ok=True)
    with open(submission_path, "w") as f:
        f.write("ProblemName,Succeeded\n")
        for result in results:
            f.write(f"{result['name']},{int(result['succeeded'])}\n")
    print(f"Submission saved to {submission_path}")

async def generate_and_evaluate(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
):
    code = await generate_solution(client, semaphore, problem)
    result = await rust_codecontests_utils.evaluate_rust_code(
        semaphore, problem, code, "./working"
    )
    # Save the generated code to a file for each problem
    problem_name = problem["name"]
    code_path = pathlib.Path("./working") / f"{problem_name}.rs"
    code_path.parent.mkdir(parents=True, exist_ok=True)
    with open(code_path, "w") as code_file:
        code_file.write(code)
    return result

# Expose the generate_solution function as required by the evaluation script

if __name__ == "__main__":
    # Run the main function using asyncio without calling asyncio.run()
    loop = asyncio.get_event_loop()
    loop.run_until_complete(main())
