)
SUM_INTS_RUST = textwrap.dedent(
    """
    use std::io::{self, Read};
    fn main() {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        let sum: i128 = s.split_whitespace().filter_map(|w| w.parse::<i128>().ok()).sum();
        println!("{}", sum);
    }
