def create_prompt(problem: dict) -> str:
    test_cases = format_test_cases(problem)
    prompt = f"""Write a Rust solution for this competitive programming problem:

Problem Name: {problem['name']}
Description: {problem['description']}

Test Cases:
{test_cases}

Requirements:
1. Use Rust 2018 edition
2. Read input from stdin
3. Write output to stdout
4. Include all necessary imports
5. Handle all test cases correctly
6. Return exactly matching output format

Provide ONLY the complete Rust code without explanations."""
    return prompt

@backoff.on_exception(
    backoff.expo,
    Exception,
    max_tries=3,
    max_time=300,
)
async def generate_solution(
    client: openai.AsyncOpenAI,
    semaphore: asyncio.Semaphore,
    problem: dict[str, Any],
) -> str:
    prompt = create_prompt(problem)
    async with semaphore:
        completion = await client.chat.completions.create(
            model="gpt-3.5-turbo-0125",
            messages=[
                {"role": "system", "content": "You are an expert Rust programmer. Generate clean, efficient, and correct competitive programming solutions. Only output the code, no explanations."},
                {"role": "user", "content": prompt}
            ],
            temperature=0.2,
            max_tokens=2000,
            presence_penalty=0.1,
            frequency_penalty=0.1,
        )
    return extract_rust_code(completion.choices[0].message.content)
