def xor_bytes(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

ciphertext = bytes.fromhex('57657535570c1e1c612b3468106a18492140662d2f5967442a2960684d28017931617b1f3637')
known_prefix = b'picoCTF{'
known_suffix = b'}'

def is_printable(byte):
    return 32 <= byte <= 126

def recover_key():
    key = bytearray()
    for i in range(len(ciphertext)):
        for k in range(256):
            if i < len(known_prefix):
                if k ^ ciphertext[i] == known_prefix[i]:
                    key.append(k)
                    break
            elif i == len(ciphertext) - 1:
                if k ^ ciphertext[i] == known_suffix[0]:
                    key.append(k)
                    break
            else:
                decrypted_byte = k ^ ciphertext[i]
                if is_printable(decrypted_byte):
                    key.append(k)
                    break
    return bytes(key)

def decrypt(key):
    return xor_bytes(ciphertext, key * (len(ciphertext) // len(key) + 1))[:len(ciphertext)]

recovered_key = recover_key()
decrypted = decrypt(recovered_key)

print(f"Recovered key: {recovered_key.hex()}")
print(f"Decrypted message: {decrypted}")

if decrypted.startswith(b'picoCTF{') and decrypted.endswith(b'}'):
    print(f"Flag found: {decrypted.decode()}")
else:
    print("Flag not found, but here's the decrypted message")

